                batch.push(line);
                if batch.len() >= 100 {
                    flush(&mut batch).await;
                }
            }
            _ = ticker.tick() => flush(&mut batch).await,
            _ = &mut shutdown => break,
        }
    }
    flush(&mut batch).await;
    Ok(())
