use std::time::Duration;

use tokio::io::{AsyncBufReadExt, BufReader};
use tokio::net::TcpStream;
use tokio::sync::oneshot;
use tokio::time::{self, MissedTickBehavior};

pub async fn run(stream: TcpStream, mut shutdown: oneshot::Receiver<()>) -> std::io::Result<()> {
    let mut lines = BufReader::new(stream).lines();
    let mut batch = Vec::new();
    let mut ticker = time::interval(Duration::from_secs(5));
    ticker.set_missed_tick_behavior(MissedTickBehavior::Delay);
    loop {
        tokio::select! {
            line = lines.next_line() => {
                let Some(line) = line? else { break };
                batch.push(line);
                if batch.len() >= 100 {
                    flush(&mut batch).await;
                }
            }
            _ = ticker.tick() => flush(&mut batch).await,
            _ = &mut shutdown => break,
        }
    }
    flush(&mut batch).await;
    Ok(())
}

async fn flush(batch: &mut Vec<String>) {
    if batch.is_empty() {
        return;
    }
    println!("flushing {} lines", batch.len());
    batch.clear();
}
